#!/usr/bin/python3
"""Public, no scene data: request a turn then forward movement and one RGB."""
import socket,http.client,json,sys,uuid
class UnixHTTP(http.client.HTTPConnection):
 def connect(self):
  self.sock=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);self.sock.connect('/relay/env.sock')
a=json.loads(sys.argv[1]);a.setdefault('action_id',str(uuid.uuid4()))
c=UnixHTTP('localhost',timeout=120);c.request('POST','/step',json.dumps(a),{'Content-Type':'application/json'});r=c.getresponse();print(r.read().decode())
